discrete InputProcessor
port:
    event input real ReceiveSignal;  // Received digital signal
event output real SendConfirmation;  // Send confirmation
state:
    initial state State1_IP
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveSignal) then
            transition(State2_IP);
        end;
    end;

    state State2_IP
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State1_IP);
            out
                send(SendConfirmation, 1);
            end;
        end;
    end;
end;

discrete ConversionController
port:
    event input real ReceiveConfirmation;  // Received confirmation signal
event output real SendCompletion;  // Send transformation completed signal
state:
    initial state State1_CC
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveConfirmation) then
            transition(State2_CC);
        end;
    end;

    state State2_CC
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State1_CC);
            out
                send(SendCompletion, 1);
            end;
        end;
    end;
end;

discrete OutputDriver
port:
    event input real ReceiveCompletion;  // Received conversion complete.
event output real GenerateAnalogSignal;  // Generate and output analogue signals
state:
    initial state State1_OD
        when entry() then
            statehold(5);
        end;
        when receive(ReceiveCompletion) then
            transition(State2_OD);
        end;
    end;

    state State2_OD
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State1_OD);
            out
                send(GenerateAnalogSignal, 1);
            end;
        end;
    end;
end;

couple DACSystem
import architectureModels.InputProcessor as IP;
import architectureModels.ConversionController as CC;
import architectureModels.OutputDriver as OD;
